from pathlib import Path
import re
ips={}
for i in range(1,41):
 s=Path(f'pc{i}.startup').read_text()
 ips[i]=re.search(r'ip address add ([\\d.]+)/\\d+ dev eth0',s).group(1)
roles={'root':1,'resolver':2,'com':3,'net':4,'edu':5,'it':6}
records={'com':{'shop.example.com':16,'blog.example.com':17,'dept.company.com':18,'intranet.company.com':19,'api.service.com':20,'mail.company.com':7},'net':{'ai.research.lab.net':22,'data.research.lab.net':23,'dev.lab.net':24,'ci.tools.net':25},'edu':{'vpn.university.edu':26,'courses.university.edu':27,'portal.campus.edu':28,'mail.university.edu':11},'it':{'studenti.unibo.it':29,'servizi.comune.it':30,'dati.regione.it':31}}
opts='directory \"/var/cache/bind\"; recursion no; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { none; };'
for zone,pc in [('root',1),('com',3),('net',4),('edu',5),('it',6)]:
 d=Path(f'pc{pc}/etc/bind'); d.mkdir(parents=True,exist_ok=True)
 origin='.' if zone=='root' else zone
 ns='a.root-servers.' if zone=='root' else f'ns.{zone}.'
 (d/'named.conf').write_text(f'options {{ {opts} }};\\nzone \"{origin}\" {{ type master; file \"/etc/bind/db.{zone}\"; }};\\n')
 lines=['"'$TTL 3600'"',f'@ IN SOA {ns} hostmaster.{\"root-servers.\" if zone==\"root\" else zone+\".\"} ( 1 3600 900 604800 300 )',f'@ IN NS {ns}']
 if zone=='root':
  lines.append(f'{ns} IN A {ips[1]}')
  for t in ('com','net','edu','it'):
   lines.extend([f'{t}. IN NS ns.{t}.',f'ns.{t}. IN A {ips[roles[t]]}'])
 else:
  lines.append(f'ns IN A {ips[pc]}')
  for name,n in records[zone].items(): lines.append(f'{name}. IN A {ips[n]}')
  if zone=='com': lines.append('company.com. IN MX 10 mail.company.com.')
  if zone=='edu': lines.append('university.edu. IN MX 10 mail.university.edu.')
 (d/f'db.{zone}').write_text('\\n'.join(lines)+'\\n')
d=Path('pc2/etc/bind'); d.mkdir(parents=True,exist_ok=True)
(d/'named.conf').write_text('options { directory \"/var/cache/bind\"; recursion yes; allow-recursion { any; }; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { none; }; };\\nzone \".\" { type hint; file \"/etc/bind/db.hints\"; };\\n')
(d/'db.hints').write_text(f'. 3600000 IN NS a.root-servers.\\na.root-servers. 3600000 IN A {ips[1]}\\n')
for i in range(1,41):
 p=Path(f'pc{i}.startup')
 with p.open('a') as f:
  f.write(f'\\n# DNS resolver for laboratory names\\necho \"nameserver {ips[2]}\" > /etc/resolv.conf\\n')
  if i in roles.values(): f.write('systemctl restart named\\n')
print('DNS roles:', {k:(f'pc{v}',ips[v]) for k,v in roles.items()})
print('Records:', {name:ips[n] for zone in records.values() for name,n in zone.items()})
PY"

